function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // DNA helix
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  for (let i = 0; i < 10; i++) {
    let x = W/2 + 50 * Math.cos(i + t);
    let y = H/2 + 50 * Math.sin(i + t);
    ctx.lineTo(x, y);
  }
  ctx.stroke();

  // Gene replication
  ctx.fillStyle = 'black';
  for (let i = 0; i < 5; i++) {
    let x = W/2 + 70 * Math.cos(i + 2 * t);
    let y = H/2 + 70 * Math.sin(i + 2 * t);
    ctx.beginPath();
    ctx.arc(x, y, 10, 0, 2 * Math.PI);
    ctx.fill();
  }

  // Stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 100, 20, 0, 2 * Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 80);
  ctx.lineTo(W/2, H/2 - 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 60);
  ctx.lineTo(W/2 - 20, H/2 - 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 60);
  ctx.lineTo(W/2 + 20, H/2 - 40);
  ctx.stroke();

  ctx.restore();
}
